// Service worker: makes the whole app, including the OCR engine and its
// language data, available with no network.
//
// VERSION and ASSETS are generated by `node tools/update-sw.mjs`.
const VERSION = 'f1fed815c7';
const ASSETS = [
  './',
  'index.html',
  'manifest.webmanifest',
  'css/app.css',
  'js/analytics/device.js',
  'js/api/client.js',
  'js/app.js',
  'js/auth/auth.js',
  'js/camera/camera.js',
  'js/config.js',
  'js/core/defaults.js',
  'js/correction/corrector.js',
  'js/detection/detector.js',
  'js/detection/quality.js',
  'js/duplicate/duplicate.js',
  'js/ocr/candidates.js',
  'js/ocr/cloud-engine.js',
  'js/ocr/engine.js',
  'js/ocr/preprocess.js',
  'js/ocr/tesseract-engine.js',
  'js/offline/db.js',
  'js/paddle/ctc.js',
  'js/paddle/db.js',
  'js/paddle/engine.js',
  'js/paddle/image.js',
  'js/pallet/assets.js',
  'js/pallet/candidate.js',
  'js/pallet/client.js',
  'js/pallet/lines.js',
  'js/pallet/parse.js',
  'js/pallet/reader.js',
  'js/pallet/tracker.js',
  'js/pallet/worker.js',
  'js/scanner/pallet-pipeline.js',
  'js/scanner/pipeline.js',
  'js/session/status.js',
  'js/session/store.js',
  'js/sync/sync.js',
  'js/tracking/tracker.js',
  'js/ui/card.js',
  'js/ui/dom.js',
  'js/ui/export.js',
  'js/ui/history.js',
  'js/ui/home.js',
  'js/ui/login.js',
  'js/ui/scanner.js',
  'js/ui/sessionview.js',
  'js/ui/sheets.js',
  'js/validation/validator.js',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-512.png',
  'icons/icon.svg',
  'vendor/fonts/b612-latin-400-normal.woff2',
  'vendor/fonts/b612-latin-700-normal.woff2',
  'vendor/fonts/b612-mono-latin-700-normal.woff2',
  'vendor/ort/ort-wasm-simd-threaded.js',
  'vendor/ort/ort.wasm.min.js',
  'vendor/tesseract/eng.traineddata.gz',
  'vendor/tesseract/tesseract-core-lstm.wasm.js',
  'vendor/tesseract/tesseract-core-relaxedsimd-lstm.wasm.js',
  'vendor/tesseract/tesseract-core-simd-lstm.wasm.js',
  'vendor/tesseract/tesseract.min.js',
  'vendor/tesseract/worker.min.js',
];

const CACHE = `uld-scanner-${VERSION}`;

// Send the two headers that make the page "cross-origin isolated". The pallet
// reader then gets several processor threads and reads roughly twice as fast.
// A static host such as GitHub Pages cannot send these headers itself, so the
// service worker adds them. Takes effect from the second time the app is
// opened. If anything misbehaves after an update, set this to false and run
// `node tools/update-sw.mjs`; the reader then simply works on one thread.
const ISOLATE = true;
function isolated(res) {
  if (!ISOLATE || !res || res.status === 0) return res;       // status 0 = opaque / redirect: pass through untouched
  const headers = new Headers(res.headers);
  headers.set('Cross-Origin-Opener-Policy', 'same-origin');
  headers.set('Cross-Origin-Embedder-Policy', 'require-corp');
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers });
}

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('uld-scanner-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('fetch', (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== location.origin) return;
  // Cache-first for the app's own precached files. Anything that is not in
  // the precache (API calls included) goes straight to the network and is
  // never stored; offline handling for data lives in the app's sync queue.
  e.respondWith(
    caches.match(e.request, { ignoreSearch: e.request.mode === 'navigate' }).then((hit) => hit || fetch(e.request).catch(() =>
      e.request.mode === 'navigate' ? caches.match('./') : Response.error())).then(isolated));
});
